// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }

    function testFuzz_property(address fuzzCaller) public {
        if (fuzzCaller == address(0)) return;

        vm.prank(fuzzCaller);
        Caller caller = new Caller(c);

        address returned = caller.callOwner();

        assertTrue(returned == address(this));
    }
}

contract Caller {
    StaxLPStaking c;
    constructor(StaxLPStaking _c) {
        c = _c;
    }
    function callOwner() external returns (address) {
        return c.owner();
    }
}
